def predict_moon_phase(n, sizes):
    if n == 1:
        return -1

    last_size = sizes[-1]

    for i in range(1, n):
        current_size = sizes[-i-1]
        if current_size < last_size:
            return "UP"
        elif current_size > last_size:
            return "DOWN"

    return "UP"

