def determine_moon_phase(n, sequence):
    if n == 1:
        return -1
    if sequence[n - 2] < sequence[n - 1]:
        return "UP"
    elif sequence[n - 2] > sequence[n - 1]:
        return "DOWN"
    else:
        return -1

